#!/usr/bin/env node
// Generates local-only wrangler config from template.toml.example semantics so the
// full storefront + admin UI runs against wrangler's LOCAL KV/R2 simulation with
// zero Cloudflare connectivity and zero real credentials.
//
// Writes: wrangler.toml, .dev.vars (worker secrets), .env.local (VITE_ client vars).
// Idempotent: generated files are always overwritten. A hand-edited wrangler.toml
// (one without the generator marker) is never touched without --force.
//
// Usage: node scripts/dev/build-local-config.mjs [--force]
import fs from 'fs'
import path from 'path'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
export const repoRoot = path.resolve(__dirname, '../..')

// Stable dummy namespace id: local KV state under .wrangler/state is keyed by id,
// so a constant keeps previously seeded data valid across regenerations.
export const LOCAL_KV_ID = '0f5e3a1c7b2d4e6f8a9b0c1d2e3f4a5b'
export const LOCAL_SITE_URL = 'http://localhost:8787'
export const LOCAL_ADMIN_PASSWORD = 'local-dev-password'
export const LOCAL_ADMIN_TOKEN = 'local-dev-admin-token'
// Reserved sentinel consumed by src/services/StripeService.js to skip remote Stripe
// sync in local dev. Never use a different value here without updating that guard.
export const LOCAL_STRIPE_SENTINEL = 'sk_test_local_no_network'
export const LOCAL_PUBLISHABLE_KEY = 'pk_test_local_no_network'
export const GENERATED_MARKER = 'Generated by scripts/dev/build-local-config.mjs'

const WRANGLER_TOML_WARNING = [
  `⚠️  wrangler.toml exists and was NOT generated by ${GENERATED_MARKER}.`,
  '   It looks hand-edited, so it was left untouched.',
  '   Re-run with --force to overwrite it with the generated local config.',
].join('\n')

export function generateWranglerToml() {
  return `# ${GENERATED_MARKER} — safe to regenerate; hand edits will be lost.
# Local development only. Never deploy this file.
name = "openshop-local"
main = "src/worker.js"
compatibility_date = "2024-09-23"
compatibility_flags = ["nodejs_compat"]

# Local-only KV namespace (dummy id backed by .wrangler/state via --local)
[[kv_namespaces]]
binding = "YOUR_STORE_KV"
id = "${LOCAL_KV_ID}"

# Local-only R2 bucket (simulated in .wrangler/state via --local)
[[r2_buckets]]
binding = "IMAGES"
bucket_name = "local-images"

[vars]
SITE_URL = "${LOCAL_SITE_URL}"

# Static assets served by the worker itself (single-process prod parity)
[assets]
directory = "dist"
binding = "ASSETS"

[observability]
enabled = true
head_sampling_rate = 1
`
}

export function generateDevVars() {
  return `# ${GENERATED_MARKER} — safe to regenerate; hand edits will be lost.
# Worker-side secrets for \`wrangler dev --local\` only. Never deploy.
ADMIN_PASSWORD=${LOCAL_ADMIN_PASSWORD}
SITE_URL=${LOCAL_SITE_URL}
STRIPE_SECRET_KEY=${LOCAL_STRIPE_SENTINEL}
`
}

export function generateEnvLocal() {
  return `# ${GENERATED_MARKER} — safe to regenerate; hand edits will be lost.
# Client-side VITE_ vars read by Vite during \`npm run dev:frontend\`.
VITE_STRIPE_PUBLISHABLE_KEY=${LOCAL_PUBLISHABLE_KEY}
`
}

function hasGeneratedMarker(content) {
  return content.includes(GENERATED_MARKER)
}

export function main(argv = process.argv.slice(2)) {
  const force = argv.includes('--force')
  const outputs = []

  const tomlPath = path.join(repoRoot, 'wrangler.toml')
  if (fs.existsSync(tomlPath) && !hasGeneratedMarker(fs.readFileSync(tomlPath, 'utf8')) && !force) {
    console.warn(WRANGLER_TOML_WARNING)
  } else {
    fs.writeFileSync(tomlPath, generateWranglerToml())
    outputs.push('wrangler.toml')
  }

  // Derived secret/env files are always regenerated (they carry no hand edits by contract).
  fs.writeFileSync(path.join(repoRoot, '.dev.vars'), generateDevVars())
  fs.writeFileSync(path.join(repoRoot, '.env.local'), generateEnvLocal())
  outputs.push('.dev.vars', '.env.local')

  console.log(`✅ Wrote: ${outputs.join(', ')}`)
  console.log(`   KV binding YOUR_STORE_KV (dummy id ${LOCAL_KV_ID}), R2 bucket local-images`)
  console.log(`   Admin password: ${LOCAL_ADMIN_PASSWORD}`)
  return 0
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  process.exit(main())
}
